def compute(vars):
    owned_facilities = vars["v1"]
    total_facilities = vars["v2"]

    if total_facilities == 0:
        value = None
    else:
        value = (owned_facilities / total_facilities) * 100

    return {
        "value": value,
        "trace": {
            "owned_facilities": owned_facilities,
            "total_facilities": total_facilities,
            "ratio": None if total_facilities == 0 else owned_facilities / total_facilities,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "percentage"
            }
        }
    }
